let mut page = use_signal(|| 1i32);
rsx! {
    Pagination::<Route> {
        variant: "admin",
        current_page: page(),
        total: 80,
        per_page: 10,
        unit: "篇",
        on_prev: move |_| page.set((page() - 1).max(1)),
