let mut open = use_signal(|| false);
let mut anchor_x = use_signal(|| 0i32);
let mut anchor_y = use_signal(|| 0i32);
rsx! {
    div {
        button {
            onclick: move |event: MouseEvent| {
                #[cfg(target_arch = "wasm32")]
                {
                    use dioxus::html::InteractionLocation;
                    let point = event.client_coordinates();
                    anchor_x.set(point.x as i32);
                    anchor_y.set(point.y as i32);
                }
                open.set(true);
            },
            "打开浮层"
        }
        Popover {
            open: open(),
            anchor_x: anchor_x(),
            anchor_y: anchor_y(),
            on_close: move |_| open.set(false),
            p { "保留这片灵感？" }
        }
    }
}

let mut visible = use_signal(|| false);
let mut closing = use_signal(|| false);
rsx! {
    div {
        button { onclick: move |_| visible.set(true), "打开弹窗" }
        ModalShell {
            visible,
            closing,
            title: "留住一片灵感",
            h2 { "留住一片灵感。" }
            button {
                onclick: move |_| {
                    closing.set(true);
                    visible.set(false);
                },
                "收好了"
            }
        }
    }
}

